// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import {
  CopyIcon,
  CreditCardIcon,
  DatabaseIcon,
  DownloadIcon,
  ShieldAlertIcon,
  TableIcon,
  WrapTextIcon,
} from 'lucide-react'

import { Btn, DemoStage, Label, PanelChrome, type Build } from '@/app/demos/stage'
import { cn } from '@/shared/utils/cn'

import { CAPTIONS, COLUMNS, CSV, CSV_RESEEDED, ROWS, SEEDS, SIZE } from './script'

const SHOWN = ['JSON', 'CSV', 'SQL']

const build: Build = ({ tl, q, qa, step, final, move, click, scramble, wait, cursorOut }) => {
  const pickFormat = (name: string) => {
    move(`fmt-${name}`)
    click(`fmt-${name}`)
    tl.to(
      qa('fmt'),
      { backgroundColor: 'rgba(255,255,255,0)', color: 'var(--demo-muted)', duration: 0.15 },
      '<',
    )
    tl.to(
      q(`fmt-${name}`),
      { backgroundColor: 'rgba(45,212,191,0.2)', color: 'var(--demo-ink)', duration: 0.15 },
      '<',
    )
  }

  step(0)
  move('preset')
  click('preset')
  tl.fromTo(
    qa('col'),
    { opacity: 0, scale: 0.7 },
    { opacity: 1, scale: 1, duration: 0.3, stagger: 0.08, ease: 'back.out(2.5)' },
    '<0.15',
  )

  step(1, '+=0.3')
  move('generate')
  click('generate')
  tl.to(q('empty'), { opacity: 0, duration: 0.2 }, '<')
  tl.fromTo(
    q('result'),
    { opacity: 0, y: 10 },
    { opacity: 1, y: 0, duration: 0.3, ease: 'power3.out' },
    '<0.1',
  )
  tl.fromTo(
    qa('trow'),
    { opacity: 0, y: -10, rotateX: -50 },
    { opacity: 1, y: 0, rotateX: 0, duration: 0.4, stagger: 0.08, ease: 'power3.out' },
    '<0.1',
  )

  step(2, '+=0.4')
  pickFormat('CSV')
  scramble('fmt-badge', 'CSV', { at: '<', duration: 0.3 })
  scramble('size', `${SIZE.csv} B`, { at: '<', duration: 0.4, chars: '0123456789' })
  move('raw', { at: '+=0.1' })
  click('raw')
  tl.to(q('raw'), { color: '#2dd4bf', duration: 0.15 }, '<')
  tl.to(q('table'), { opacity: 0, duration: 0.2 }, '<')
  tl.fromTo(
    qa('csv-line'),
    { opacity: 0, x: -10 },
    { opacity: 1, x: 0, duration: 0.25, stagger: 0.05 },
    '<0.1',
  )

  step(3, '+=0.4')
  move('reseed')
  click('reseed')
  scramble('seed', SEEDS[1], { at: '<', duration: 0.4, chars: '0123456789' })
  qa('csv-line').forEach((line, index) => {
    if (index === 0) return
    scramble(line, CSV_RESEEDED[index], {
      at: index === 1 ? '<0.1' : '<0.05',
      duration: 0.6,
      chars: 'abcdefghijklmnopqrstuvwxyz',
    })
  })
  move('copy', { at: '+=0.2' })
  click('copy')
  tl.to(q('copy-text'), { text: 'Copied', duration: 0.01 }, '<')
  cursorOut('+=0.3')
  final()
  wait(1.4)
}

export default function Demo() {
  return (
    <DemoStage
      label="Test Data Generator building user rows from a preset, exporting CSV and reseeding"
      steps={CAPTIONS}
      build={build}
    >
      <PanelChrome>
        <div className="flex h-full flex-col gap-2">
          <div className="flex gap-1 text-[10px]">
            {[
              { name: 'Dataset', Icon: DatabaseIcon },
              { name: 'Edge cases', Icon: ShieldAlertIcon },
              { name: 'Payments', Icon: CreditCardIcon },
            ].map(({ name, Icon }, index) => (
              <span
                key={name}
                className={cn(
                  'flex items-center gap-1 rounded-full px-2.5 py-1',
                  index === 0 ? 'bg-ink/10 text-ink' : 'text-muted',
                )}
              >
                <Icon className="size-3" /> {name}
              </span>
            ))}
          </div>
          <div className="flex items-end gap-2">
            <div>
              <Label>Preset</Label>
              <span
                data-d="preset"
                className="mt-1 flex h-7 items-center rounded-lg border border-line bg-canvas/80 px-2 text-[10px] text-ink"
              >
                User account ▾
              </span>
            </div>
            <div>
              <Label>Rows</Label>
              <span className="mt-1 flex h-7 w-10 items-center rounded-lg border border-line bg-canvas/80 px-2 font-mono text-[10px]">
                {ROWS.length}
              </span>
            </div>
            <div>
              <Label>Seed</Label>
              <span className="mt-1 flex h-7 items-center gap-1.5 rounded-lg border border-line bg-canvas/80 pl-2 pr-1 font-mono text-[10px]">
                <span data-d="seed">{SEEDS[0]}</span>
                <span
                  data-d="reseed"
                  className="rounded-md bg-ink/10 px-1.5 py-0.5 font-sans text-[9px] text-ink-soft"
                >
                  New seed
                </span>
              </span>
            </div>
            <div className="ml-auto">
              <Label>Format</Label>
              <span className="mt-1 flex h-7 items-center gap-0.5 rounded-lg border border-line bg-canvas/80 p-0.5 text-[9.5px]">
                {SHOWN.map((name, index) => (
                  <span
                    key={name}
                    data-d={`fmt fmt-${name}`}
                    className={cn(
                      'rounded-md px-1.5 py-1',
                      index === 0 ? 'bg-[#2dd4bf]/20 text-ink' : 'text-muted',
                    )}
                  >
                    {name}
                  </span>
                ))}
              </span>
            </div>
          </div>
          <div className="flex items-center gap-1.5">
            {COLUMNS.map((column) => (
              <span
                key={column.name}
                data-d="col"
                className="rounded-md border border-line-strong px-1.5 py-0.5 font-mono text-[9px] text-ink-soft"
              >
                {column.name} <span className="text-muted">· {column.type}</span>
              </span>
            ))}
            <span className="text-[9px] text-muted">+ Add column</span>
            <Btn d="generate" primary>
              Generate
            </Btn>
          </div>

          <div className="relative min-h-0 flex-1">
            <div
              data-d="empty"
              className="absolute inset-0 flex items-center justify-center rounded-xl border border-dashed border-line-strong text-[10px] text-muted"
            >
              Choose a schema and generate rows
            </div>
            <div
              data-d="result"
              className="absolute inset-0 flex flex-col overflow-hidden rounded-xl border border-line bg-canvas/60 opacity-0"
            >
              <div className="flex items-center gap-1.5 border-b border-line px-2 py-1.5 text-[9px]">
                <span className="rounded-full bg-ink/10 px-1.5 py-0.5 text-ink">
                  {ROWS.length} rows
                </span>
                <span
                  data-d="fmt-badge"
                  className="rounded-full border border-line-strong px-1.5 py-0.5 text-ink-soft"
                >
                  JSON
                </span>
                <span data-d="size" className="font-mono text-muted">
                  {SIZE.json} B
                </span>
                <span className="ml-auto flex items-center gap-1.5 text-muted">
                  <TableIcon className="size-3 text-ink" />
                  <span data-d="raw">
                    <WrapTextIcon className="size-3" />
                  </span>
                  <span data-d="copy" className="flex items-center gap-1">
                    <CopyIcon className="size-3" /> <span data-d="copy-text">Copy</span>
                  </span>
                  <DownloadIcon className="size-3" />
                </span>
              </div>
              <div className="relative min-h-0 flex-1 [perspective:600px]">
                <table
                  data-d="table"
                  className="absolute inset-x-0 top-0 w-full text-left text-[9.5px]"
                >
                  <thead className="text-muted">
                    <tr>
                      {COLUMNS.map((column) => (
                        <th key={column.name} className="px-2 py-1 font-mono font-normal">
                          {column.name}
                        </th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    {ROWS.map((row) => (
                      <tr key={row[0]} data-d="trow" className="border-t border-line">
                        <td className="px-2 py-1 text-ink">{row[0]}</td>
                        <td className="px-2 py-1 font-mono text-ink-soft">{row[1]}</td>
                        <td
                          className={cn(
                            'px-2 py-1 font-mono',
                            row[2] ? 'text-emerald' : 'text-muted',
                          )}
                        >
                          {String(row[2])}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
                <pre className="absolute inset-0 overflow-hidden p-2 font-mono text-[9.5px] leading-[16px] text-ink-soft">
                  {CSV.map((line, index) => (
                    <span
                      key={index}
                      data-d="csv-line"
                      className={cn('block opacity-0', index === 0 && 'text-[#2dd4bf]')}
                    >
                      {line}
                    </span>
                  ))}
                </pre>
              </div>
            </div>
          </div>
        </div>
      </PanelChrome>
    </DemoStage>
  )
}
